-- seed part 11 · products (10 of 10) — run parts in order
on conflict (slug) do update set slug = excluded.slug, name = excluded.name, category = excluded.category, description = excluded.description, image = excluded.image, price = excluded.price, currency = excluded.currency, status = excluded.status, delivery_info = excluded.delivery_info, file_url = excluded.file_url, featured = excluded.featured, sort_order = excluded.sort_order, seo = excluded.seo, archived = excluded.archived;
